CREATE OR REPLACE FUNCTION public.continue_with_fabric_shortage(p_order_id uuid, p_status text, p_status_key text, p_notes text, p_op_id uuid, p_history_note text, p_fabric_lines jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
